def semver_sort(versions):
    def parse_version(version_str):
        # Split by '+' to remove build metadata
        version_without_build = version_str.split('+')[0]

        # Split by '-' to separate core version and pre-release
        if '-' in version_without_build:
            core, prerelease = version_without_build.split('-', 1)
        else:
            core = version_without_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
        else:
            prerelease_ids = None

        return (major, minor, patch, prerelease_ids)

    def prerelease_key(prerelease_ids):
        if prerelease_ids is None:
            # No pre-release sorts after pre-release
            return (1,)

        # Convert pre-release identifiers to comparable form
        ids = []
        for identifier in prerelease_ids:
            if identifier.isdigit():
                # All-digit identifiers compare numerically
                ids.append((0, int(identifier)))
            else:
                # Other identifiers compare by ASCII order
                ids.append((1, identifier))

        return (0, tuple(ids))

    def sort_key(version_str):
        major, minor, patch, prerelease_ids = parse_version(version_str)
        return (major, minor, patch, prerelease_key(prerelease_ids))

    # Stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

